package com.pizzalab.batch;
import com.pizzalab.model.Order; import com.pizzalab.repository.OrderRepository; import org.springframework.batch.core.*; import org.springframework.batch.core.job.builder.JobBuilder; import org.springframework.batch.core.repository.JobRepository; import org.springframework.batch.core.repository.support.ResourcelessJobRepository; import org.springframework.batch.core.step.builder.StepBuilder; import org.springframework.batch.item.*; import org.springframework.batch.item.support.ListItemReader; import org.springframework.context.annotation.*; import org.springframework.batch.core.configuration.annotation.StepScope; import org.springframework.batch.core.configuration.annotation.EnableBatchProcessing; import org.springframework.beans.factory.annotation.Value; import org.springframework.transaction.PlatformTransactionManager; import org.springframework.core.task.SyncTaskExecutor; import org.springframework.batch.core.launch.*; import org.springframework.batch.core.launch.support.TaskExecutorJobLauncher; import java.time.LocalDate; import java.util.List;
/** Configura un Job Spring Batch real: Reader de pedidos, Processor de validación y Writer por chunks de dos. */
@Configuration @EnableBatchProcessing public class BatchConfig {
 @Bean JobRepository jobRepository(){return new ResourcelessJobRepository();}
 @Bean JobLauncher jobLauncher(JobRepository repo)throws Exception{TaskExecutorJobLauncher launcher=new TaskExecutorJobLauncher();launcher.setJobRepository(repo);launcher.setTaskExecutor(new SyncTaskExecutor());launcher.afterPropertiesSet();return launcher;}
 @Bean @StepScope ItemReader<Order> orderReader(OrderRepository orders,@Value("#{jobParameters['date']}") String date){List<Order> source=orders.findForDate(LocalDate.parse(date));return new ListItemReader<>(source);}
 @Bean ItemProcessor<Order,Order> orderProcessor(){return order->{if(order.totalCents()<0)throw new IllegalStateException("Pedido con total inválido");return order;};}
 @Bean Step salesAggregationStep(JobRepository repo,PlatformTransactionManager tx,ItemReader<Order> reader,ItemProcessor<Order,Order> processor,ReportCollector writer){return new StepBuilder("agregar-ventas",repo).<Order,Order>chunk(2,tx).reader(reader).processor(processor).writer(writer).build();}
 @Bean Job salesReportJob(JobRepository repo,Step salesAggregationStep,ReportCollector collector){return new JobBuilder("reporte-ventas",repo).listener(collector).start(salesAggregationStep).build();}
}
